mapper.select:
WITH calc_set AS ( SELECT /*LGVPAY00007.retrievePayrollActivityList*/ tpcs.payroll_calculation_set_name , tpcs.auto_creation_flag FROM tb_pay_calc_set_n tpcs WHERE tpcs.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} AND tpcs.payroll_calculation_set_id = #{calculationSetId, jdbcType=NUMERIC} ) SELECT a.process_no , a.process_group_name , a.process_name , a.process_desc , NVL(b.completion_flag,'N') AS completion_flag , TO_CHAR(b.completion_date, 'DD/MM/YYYY HH24:MI:SS') AS completion_date , calc_set.payroll_calculation_set_name , CASE WHEN a.process_group_name = 'TRANSFER_ERP' THEN 'Y' WHEN a.process_group_name = 'REQUEST_PAYROLL_CONFIRM' THEN 'R' WHEN a.process_group_name = 'CREATE_EMPLOYEE' AND NVL(calc_set.auto_creation_flag, 'N') = 'Y' THEN 'Y' /* 자동생성인 경우만 대상자 생성 버튼 보여줌 */ ELSE 'N' END AS run_btn_display_flag , a.batch_program_full_name , 'Y' AS retire_flag /* 퇴직여부. 급여대상자 생성시 필요한 파라메터. 현재는 Y로 고정 */ ,( SELECT pce.payroll_calculation_exec_id FROM tb_pay_calc_exec_n pce , tb_pay_calc_period_basis_n pcpb WHERE pce.payroll_calculation_set_id = #{calculationSetId, jdbcType=NUMERIC} AND pce.payroll_type_code = a.payroll_type_code AND pcpb.subsidiary_code = a.subsidiary_code AND pcpb.payroll_calc_period_value = TO_CHAR(TO_DATE(#{payrollCalcPeriodValue},'mm/yyyy'),'yyyymm') AND pce.basis_date BETWEEN to_date(pcpb.start_yyyymmdd, 'yyyymmdd') AND to_date(pcpb.end_yyyymmdd, 'yyyymmdd') AND pce.confirm_flag = 'Y' /* 확정된 calculation_exec_id 조회 */ ) AS payroll_calculation_exec_id /* 급여 전표 인터페이스 데이터 생성 시 필요한 파라메터. payMonth, payType, calculationSetId 로 조회한 실행 건 중 확정된 exec_id */ ,NVL(( SELECT CASE WHEN larn.status_code IN ( 40, 50 ) OR pce.request_master_id IS NULL THEN 'Y' ELSE 'N' END FROM tb_pay_calc_exec_n pce , tb_pay_calc_period_basis_n pcpb , lgcom_approval_request_n larn WHERE pce.payroll_calculation_set_id = #{calculationSetId, jdbcType=NUMERIC} AND pce.payroll_type_code = a.payroll_type_code AND pcpb.subsidiary_code = a.subsidiary_code AND pce.request_master_id = larn.request_master_id(+) AND pce.request_code = larn.request_code(+) AND pcpb.payroll_calc_period_value = TO_CHAR(TO_DATE(#{payrollCalcPeriodValue},'mm/yyyy'),'yyyymm') AND pce.basis_date BETWEEN to_date(pcpb.start_yyyymmdd, 'yyyymmdd') AND to_date(pcpb.end_yyyymmdd, 'yyyymmdd') AND pce.confirm_flag = 'Y' /* 확정된 calculation_exec_id 조회 */ ), 'Y') AS approved_flag FROM tb_pay_payroll_process_m a , tb_pay_procs_perfm_result_n b , calc_set WHERE a.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} AND a.payroll_type_code = #{payrollTypeCode}
AND a.process_no = #{srchProcessNo}
AND b.process_no(+) = a.process_no AND b.basis_yyyymm(+) = TO_CHAR(TO_DATE(#{payrollCalcPeriodValue},'mm/yyyy'),'yyyymm') AND b.payroll_calculation_set_id(+) = #{calculationSetId, jdbcType=NUMERIC} ORDER BY sort_order_no

SELECT CASE WHEN COUNT(*) > 0 THEN 'Y' ELSE 'N' END as exists_flag
FROM   tb_pay_procs_perfm_result_n b
WHERE  b.process_no                 = #{processNo, jdbcType=NUMERIC}
AND    b.basis_yyyymm               = TO_CHAR(TO_DATE(#{payrollCalcPeriodValue},'mm/yyyy'),'yyyymm')
AND    b.payroll_calculation_set_id = #{calculationSetId, jdbcType=NUMERIC}
